import { useMemo, useCallback } from 'react';

const METRICS_SUB = gql`
  subscription OnMetricsUpdate {
    metricsUpdated {
      cpu
      memory
      requestsPerSecond
      timestamp
    }
  }
`;

function MetricsDashboard() {
  const [metrics, setMetrics] = useState([]);

  useSubscription(METRICS_SUB, {
    onSubscriptionData: ({ subscriptionData }) => {
      const point = subscriptionData.data.metricsUpdated;
      setMetrics((prev) => {
        const next = [...prev, point];
        return next.slice(-100); // Keep last 100 points
      });
    },
  });

  const latestCpu = useMemo(() => {
    return metrics[metrics.length - 1]?.cpu ?? 0;
