useSubscription(ON_TASK_UPDATED, {
  onSubscriptionData: ({ client, subscriptionData }) => {
    const updatedTask = subscriptionData.data.taskUpdated;

    client.cache.updateFragment({
      id: client.cache.identify({ __typename: 'Task', id: updatedTask.id }),
      fragment: gql`
        fragment TaskFragment on Task {
          status
          progress
          updatedAt
        }
      `,
      data: {
        status: updatedTask.status,
        progress: updatedTask.progress,
        updatedAt: updatedTask.updatedAt,
      },
    });
  },
});

useSubscription(ON_USER_STATUS_CHANGED, {
  onSubscriptionData: ({ client, subscriptionData }) => {
    const { userId, status } = subscriptionData.data.userStatusChanged;

    client.cache.modify({
      id: client.cache.identify({ __typename: 'User', id: userId }),
      fields: {
        status: () => status,
        lastSeen: () => new Date().toISOString(),
      },
    });
  },
});
